using System;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnSpecificDiceTierOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnSpecificDiceTierOmenData")]
public class OnSpecificDiceTierOmenData : OmenData
{
	private const string everyXDiceTierPlayedID = "EveryXDiceTierPlayed";

	private const string gainWithDrawBackChantID = "GainWithDrawBackChant";

	private const string wheneverPlayADieID = "WheneverPlayADie";

	[Header("OnSpecificDiceTier Omen")]
	[SerializeField]
	[HideIf("disableDiceTier")]
	protected DiceTier diceTier;

	[SerializeField]
	private bool activateOmenBeforeActionCasted;

	[SerializeField]
	private bool enableSecondAction;

	[SerializeField]
	[ShowIf("enableSecondAction")]
	protected OmenLogicActionFace secondOmenLogicActionFace;

	[Space(50f)]
	[SerializeField]
	protected bool corruptionNotIncreasedByCorruptionModifier;

	[SerializeField]
	private bool enableUseCharacterDie;

	[SerializeField]
	[ShowIf("enableUseCharacterDie")]
	private Character characterDie;

	[SerializeField]
	protected bool ignoreDiceToCompare;

	[SerializeField]
	private bool ignoreUpdateCounter;

	[SerializeField]
	private bool anyDiePlayed;

	[SerializeField]
	private bool onlyPlayerDice;

	[Header("Run Modifier")]
	[SerializeField]
	private bool usedAsRunModifierOmenData;

	[Header("Sovereigns Card")]
	[SerializeField]
	private bool sovereignsCard;

	protected Action<Dice> omenAction;

	private bool disableDiceTier
	{
		get
		{
			if (!enableUseCharacterDie)
			{
				return ignoreDiceToCompare;
			}
			return true;
		}
	}

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = GetOmenAction(omenInstance);
		if (activateOmenBeforeActionCasted)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.OnSpecificDiceUsedBeforeCastActions.Add(omenAction);
		}
		else
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.OnSpecificDiceUsedActions.Add(omenAction);
		}
	}

	public virtual Action<Dice> GetOmenAction(OmenInstance omenInstance)
	{
		return delegate(Dice dieToCompare)
		{
			if (!AlreadyUsed)
			{
				bool flag = false;
				if (ignoreDiceToCompare)
				{
					flag = true;
				}
				else if (enableUseCharacterDie)
				{
					if (dieToCompare is PlayerDice && (dieToCompare as PlayerDice).Character == characterDie)
					{
						flag = true;
					}
				}
				else if (dieToCompare.DiceTier == diceTier)
				{
					flag = true;
				}
				if ((!onlyPlayerDice || ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance.ActionOwner)) && flag)
				{
					if (EnableOmenCounter && !usedAsRunModifierOmenData)
					{
						if (OmenTriggered())
						{
							omenInstance.EnqueueOmenFeedbackAndPlay();
							omenInstance.StopBlinkingFeedback();
						}
						else if (OmenAboutToTrigger())
						{
							omenInstance.PlayBlinkingFeedback();
						}
					}
					ActivateOmen();
					if (!usedAsRunModifierOmenData && !ignoreUpdateCounter)
					{
						if (EnableOmenCounter)
						{
							omenInstance.UpdateOmenCounter();
						}
						else
						{
							omenInstance.EnqueueOmenFeedbackAndPlay();
						}
					}
				}
			}
		};
	}

	protected override void OmenLogicActiveOmen(int actionAmount, GameObject target = null, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		if (enableSecondAction)
		{
			if (corruptionNotIncreasedByCorruptionModifier)
			{
				base.OmenLogicActiveOmen(actionAmount, target, CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION);
				secondOmenLogicActionFace.ActivateOmen(target, null, CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION);
			}
			else
			{
				base.OmenLogicActiveOmen(actionAmount, target);
				secondOmenLogicActionFace.ActivateOmen(target);
			}
		}
		else if (corruptionNotIncreasedByCorruptionModifier)
		{
			base.OmenLogicActiveOmen(actionAmount, target, CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION);
		}
		else
		{
			base.OmenLogicActiveOmen(actionAmount, target);
		}
	}

	protected bool OmenTriggered()
	{
		return counter == TriggerAmount - 1;
	}

	protected bool OmenAboutToTrigger()
	{
		return counter == TriggerAmount - 2;
	}

	public override void OmenRemoved()
	{
		if (activateOmenBeforeActionCasted)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.OnSpecificDiceUsedBeforeCastActions.Remove(omenAction);
		}
		else
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.OnSpecificDiceUsedActions.Remove(omenAction);
		}
	}

	public override string OmenConvertedDescription()
	{
		string text = "";
		if (anyDiePlayed)
		{
			text = Smart.Format(base.localizationManager.GetLocalizedString("WheneverPlayADie"), GetFirstPartAfterDicerTierPlayerLocalizedDescription());
		}
		else
		{
			string text2 = "";
			string text3 = "";
			text3 = ((!enableUseCharacterDie) ? diceTier.GetLocalizedDiceTierWithDie() : base.localizationManager.GetLocalizedNeutralDie());
			if (EnableOmenCounter)
			{
				text2 = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("EveryXDiceTierPlayed");
				text2 = Smart.Format(text2, TriggerAmount, text3);
			}
			else if (sovereignsCard)
			{
				text2 = "Whenever you play an Epic Die,";
			}
			else
			{
				text2 = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedWheneverYouPlayA();
				text2 = Smart.Format(text2, text3);
			}
			if (enableSecondAction)
			{
				text = text2 + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + Smart.Format(base.localizationManager.GetLocalizedString("GainWithDrawBackChant"), GetFirstPartAfterDicerTierPlayerLocalizedDescription().RemoveLastIfDotOrComma(), secondOmenLogicActionFace.GetActionDescription().LowercaseFirst());
				if (corruptionNotIncreasedByCorruptionModifier)
				{
					text = text + "\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier();
				}
				return CheckAppendCounterKeptBetweenBattlesDescription(text);
			}
			text = text2 + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + GetFirstPartAfterDicerTierPlayerLocalizedDescription();
		}
		if (corruptionNotIncreasedByCorruptionModifier)
		{
			text = text + "\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier();
		}
		return CheckAppendCounterKeptBetweenBattlesDescription(text);
	}

	protected virtual string GetFirstPartAfterDicerTierPlayerLocalizedDescription()
	{
		return GetOmenConvertedDescriptionBattleAction().LowercaseFirst();
	}
}
